import { createCn } from 'cn/config'

/**
 * Merges class names and resolves conflicting Tailwind utilities (the caller's classes win).
 * Exposed from one project path, as `components.json` expects for code generated by the shadcn CLI.
 *
 * The custom font-size tokens from `src/index.css` are registered in the `font-size` group;
 * otherwise `text-eta` would be taken for a text colour and dropped when merged with `text-info`.
 */
export const cn = createCn({
  extend: {
    classGroups: {
      'font-size': [{ text: ['caption', 'eta', 'ai-title', 'ai-body', 'ai-footer'] }],
    },
  },
})
